    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function closeDefectsLiabilityPeriod(string $organisationId,string $userId,string $role,string $id,array $input):array
    {
        $this->confirmed($input,'closeout_review_confirmation_required');$reason=$this->text($input['reason']??null,1000,'closeout_review_reason_required');$row=$this->scope('closeout_defects_liability_periods',$organisationId,$userId,$id,'closeout_liability_period_not_found');$this->professional($organisationId,$userId,$role,$row['project_id']);if($row['ends_on']>=(new DateTimeImmutable('now'))->format('Y-m-d'))throw new CloseoutException('closeout_liability_period_not_elapsed');$s=$this->pdo->prepare("SELECT COUNT(*) FROM closeout_defect_items WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND liability_period_id=UNHEX(:id) AND status<>'verified_closed'");$s->execute(['o'=>$organisationId,'p'=>$row['project_id'],'id'=>$id]);if((int)$s->fetchColumn()>0)throw new CloseoutException('closeout_liability_defects_open');return$this->transaction(function()use($organisationId,$userId,$id,$row,$reason):array{$this->pdo->prepare("UPDATE closeout_defects_liability_periods SET status='closed',retention_release_recommended=TRUE,closed_by=UNHEX(:u),closed_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)")->execute(['u'=>$userId,'id'=>$id,'o'=>$organisationId]);$this->record($organisationId,$row['project_id'],$userId,'defects_liability','Defects liability period closed','approved',['liabilityPeriodId'=>$id,'reason'=>$reason,'retentionReleaseRecommended'=>true,'movesMoney'=>false],[$id]);$this->inbox($organisationId,$row['project_id'],'closeout.retention_release_review_due','Retention release review due','The defects-liability period is closed. Finance approvals and provider status remain required.','high',['liabilityPeriodId'=>$id,'movesMoney'=>false]);$this->audit($organisationId,$userId,'closeout.defects_liability_closed','defects_liability',$id,['reason'=>$reason,'retentionReleaseRecommended'=>true]);return$this->liability($organisationId,$row['project_id'],$id);});
