    /** @param array<string,mixed> $input @return array<string,mixed> */
    private function defectTransition(string$o,string$u,string$id,string$from,string$to,string$action,array$input,bool$reasonRequired):array{$this->confirmed($input,'closeout_confirmation_required');$reason=$reasonRequired?$this->text($input['reason']??null,1000,'closeout_reason_required'):'';$row=$this->scope('closeout_defect_items',$o,$u,$id,'closeout_defect_not_found');if($row['status']!==$from)throw new CloseoutException('closeout_defect_transition_invalid');return$this->transaction(function()use($o,$u,$id,$row,$to,$action,$reason):array{$this->pdo->prepare('UPDATE closeout_defect_items SET status=:status WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)')->execute(['status'=>$to,'id'=>$id,'o'=>$o]);$this->inbox($o,$row['project_id'],$action,'Contractor recall: '.$row['title'],$reason,'high',['defectId'=>$id]);$this->audit($o,$u,$action,'defect_closeout',$id,['reason'=>$reason]);return$this->defect($o,$row['project_id'],$id);});}
    /** @param array<string,mixed> $payload */ private function outputs(string$o,string$p,string$u,string$type,string$id,string$title,string$status,array$payload,string$severity):void{$this->record($o,$p,$u,$type,$title,$status,$payload,[$id]);if($status==='blocked'||$severity==='high')$this->inbox($o,$p,'closeout.'.$type.'_attention',$title,implode('; ',$payload['blockers']??[$status]),$severity,[$type.'Id'=>$id]);$this->recommend($o,$p,$type,$id,'Review '.$title,'Closeout evidence contains a blocker or controlled decision requiring human review.',$severity);$this->audit($o,$u,'closeout.'.$type.'_assessed',$type,$id,$payload);}
    /** @param array<string,mixed> $payload @param list<string> $links */ private function record(string$o,string$p,string$u,string$type,string$title,string$status,array$payload,array$links):void{$recordStatus=match($status){'draft'=>'draft','issued'=>'issued','superseded'=>'superseded','rejected'=>'rejected','approved','client_accepted','reviewed','verified_closed','closed'=>'approved','missing'=>'missing',default=>'pending_review'};$payload=['workflowStatus'=>$status]+$payload;$this->pdo->prepare("INSERT INTO project_records(id,organisation_id,project_id,phase,module_key,record_type,title,status,payload,approvals,linked_record_ids,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'closeout',:module,:type,:title,:status,:payload,'{\"required\":false}',:links,UNHEX(:u))")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'module'=>self::MODULE,'type'=>$type,'title'=>substr($title,0,220),'status'=>$recordStatus,'payload'=>$this->json($payload),'links'=>$this->json($links),'u'=>$u]);}
    /** @param array<string,mixed> $payload */ private function inbox(string$o,string$p,string$type,string$title,string$detail,string$priority,array$payload):void{$this->pdo->prepare('INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),\'member\',:type,:title,:detail,:priority,:payload)')->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'title'=>substr($title,0,220),'detail'=>substr($detail,0,1000),'priority'=>in_array($priority,['low','medium','high','critical'],true)?$priority:'medium','payload'=>$this->json($payload)]);}
    private function recommend(string$o,string$p,string$type,string$id,string$title,string$rationale,string$severity):void{$this->pdo->prepare("INSERT INTO closeout_agent_recommendations(id,organisation_id,project_id,source_type,source_object_id,title,rationale,severity,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:type,UNHEX(:source),:title,:rationale,:severity,'open')")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'source'=>$id,'title'=>substr($title,0,220),'rationale'=>substr($rationale,0,1000),'severity'=>$severity]);}
    /** @param array<string,mixed> $metadata */ private function audit(string$o,string$u,string$action,string$type,string$id,array$metadata):void{(new AuditService($this->pdo))->append($o,$u,$action,$type,$id,$metadata);}
    /** @return array<string,mixed> */ private function practicalCompletion(string$o,string$p,string$id):array{return$this->one('closeout_practical_completions',$o,$p,$id,['checklist','blockers']);}
    /** @return array<string,mixed> */ private function occupation(string$o,string$p,string$id):array{return$this->one('closeout_occupation_readiness',$o,$p,$id,['utilities_checklist','blockers']);}
    /** @return array<string,mixed> */ private function document(string$o,string$p,string$id):array{return$this->one('closeout_handover_documents',$o,$p,$id,[]);}
    /** @return array<string,mixed> */ private function defect(string$o,string$p,string$id):array{return$this->one('closeout_defect_items',$o,$p,$id,['evidence_ids','corrective_evidence_ids']);}
    /** @return array<string,mixed> */ private function finalAccount(string$o,string$p,string$id):array{return$this->one('closeout_final_account_readiness',$o,$p,$id,['blockers']);}
    /** @return array<string,mixed> */ private function liability(string$o,string$p,string$id):array{return$this->one('closeout_defects_liability_periods',$o,$p,$id,[]);}
    /** @return array<string,mixed> */ private function handoverPack(string$o,string$p,string$id):array{$pack=$this->one('closeout_handover_packs',$o,$p,$id,['blockers']);$s=$this->pdo->prepare('SELECT *,LOWER(HEX(id)) id FROM closeout_handover_documents WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND handover_pack_id=UNHEX(:id) ORDER BY created_at,id');$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);$pack['documents']=array_map(fn($r)=>$this->camel($r),$s->fetchAll());return$pack;}
    /** @param list<string> $json @return array<string,mixed> */ private function one(string$table,string$o,string$p,string$id,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new CloseoutException('closeout_record_not_found');foreach($json as$c)$r[$c]=$this->decode($r[$c]);return$this->camel($r);}
    /** @param list<string> $json @return list<array<string,mixed>> */ private function all(string$table,string$o,string$p,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at,id");$s->execute(['o'=>$o,'p'=>$p]);$out=[];foreach($s->fetchAll()as$r){foreach($json as$c)$r[$c]=$this->decode($r[$c]);$out[]=$this->camel($r);}return$out;}
    /** @return array<string,mixed> */ private function camel(array$r):array{$out=[];foreach($r as$key=>$value){if(in_array($key,['organisation_id','project_id'],true))continue;$name=preg_replace_callback('/_([a-z])/',static fn($m)=>strtoupper($m[1]),(string)$key);if(is_string($value)&&strlen($value)===16&&($key==='id'||str_ends_with((string)$key,'_id')||str_ends_with((string)$key,'_by')))$value=bin2hex($value);if(in_array($key,['represents_municipal_approval','municipal_certificate_verified','insurance_transition_confirmed','moves_money','retention_release_recommended'],true))$value=(bool)$value;$out[$name]=$value;}return$out;}
    /** @return array<string,mixed> */ private function scope(string$table,string$o,string$u,string$id,string$error):array{$s=$this->pdo->prepare("SELECT t.*,LOWER(HEX(t.project_id)) project_id FROM $table t JOIN organisation_memberships m ON m.organisation_id=t.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE t.organisation_id=UNHEX(:o) AND t.id=UNHEX(:id)");$s->execute(['u'=>$u,'o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new CloseoutException($error);return$r;}
    private function assertProject(string$o,string$u,string$p):void{$s=$this->pdo->prepare("SELECT 1 FROM projects p JOIN organisation_memberships m ON m.organisation_id=p.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE p.organisation_id=UNHEX(:o) AND p.id=UNHEX(:p)");$s->execute(['u'=>$u,'o'=>$o,'p'=>$p]);if($s->fetchColumn()===false)throw new CloseoutException('closeout_project_not_found');}
    private function writer(string$o,string$u,string$role):void{if(!in_array($role,['owner','administrator','admin','member'],true))throw new CloseoutException('closeout_write_forbidden');$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new CloseoutException('closeout_write_forbidden');}
    private function professional(string$o,string$u,string$role,string$p):void{if(in_array($role,['owner','administrator','admin'],true))return;$s=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND user_id=UNHEX(:u) AND status='active' AND discipline IN ('architect','engineer','quantity_surveyor')");$s->execute(['o'=>$o,'p'=>$p,'u'=>$u]);if($s->fetchColumn()===false)throw new CloseoutException('closeout_professional_authority_required');}
    private function assertOwned(string$table,string$o,string$p,string$id,string$error):void{$s=$this->pdo->prepare("SELECT 1 FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);if($s->fetchColumn()===false)throw new CloseoutException($error);}
    /** @param list<string> $statuses */ private function assertOwnedStatus(string$table,string$o,string$p,string$id,array$statuses,string$error):void{$this->assertOwned($table,$o,$p,$id,$error);$marks=implode(',',array_fill(0,count($statuses),'?'));$s=$this->pdo->prepare("SELECT 1 FROM $table WHERE organisation_id=UNHEX(?) AND project_id=UNHEX(?) AND id=UNHEX(?) AND status IN ($marks)");$s->execute(array_merge([$o,$p,$id],$statuses));if($s->fetchColumn()===false)throw new CloseoutException($error);}
    private function count(string$sql,string$o,string$p):int{$s=$this->pdo->prepare($sql);$s->execute(['o'=>$o,'p'=>$p]);return(int)$s->fetchColumn();}
    private function baselineCount(string$sql,string$o,string$b):int{$s=$this->pdo->prepare($sql);$s->execute(['o'=>$o,'b'=>$b]);return(int)$s->fetchColumn();}
    /** @template T @param callable():T $operation @return T */ private function transaction(callable$operation):mixed{$this->pdo->beginTransaction();try{$v=$operation();$this->pdo->commit();return$v;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    /** @param array<string,mixed> $input */ private function confirmed(array$input,string$error):void{if(($input['humanConfirmed']??false)!==true)throw new CloseoutException($error);}
    private function text(mixed$v,int$max,string$error):string{if(!is_string($v)||trim($v)===''||mb_strlen(trim($v))>$max)throw new CloseoutException($error);return trim($v);}
    private function choice(mixed$v,array$choices,string$error):string{if(!is_string($v)||!in_array($v,$choices,true))throw new CloseoutException($error);return$v;}
    private function id(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new CloseoutException($error);return strtolower($v);}
    private function nullableId(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->id($v,$error);}
    /** @return list<string> */ private function ids(mixed$v,string$error):array{if(!is_array($v)||count($v)>100)throw new CloseoutException($error);return array_values(array_unique(array_map(fn($id)=>$this->id($id,$error),$v)));}
    private function date(mixed$v,string$error):string{if(!is_string($v)||DateTimeImmutable::createFromFormat('!Y-m-d',$v)?->format('Y-m-d')!==$v)throw new CloseoutException($error);return$v;}
    private function json(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}
    private function decode(mixed$v):array{if(!is_string($v))return[];$d=json_decode($v,true,512,JSON_THROW_ON_ERROR);return is_array($d)?$d:[];}
